  var incomingCommands = {"general":[["/help","Vozen의 명령어 목록 보기"],["/join","음성 채널에 참여"],["/leave","음성 채널에서 나가기"],["/tts","텍스트를 소리 내어 읽기"],["/tts-file","Create a private audio file without joining a call"],["/translate text","Translate text privately, including as a User App"],["/skip","현재 오디오 건너뛰기"],["/shut-up","지금 바로 Vozen 조용히 시키기 (대기열 비우기)"],["/setup","단계별 원스텝 설정"],["/invite","초대 링크 받기"],["/vote","top.gg에서 Vozen에 투표"],["/uptime","Vozen이 온라인 상태인 시간"],["/premium","서버와 나의 Premium 상태"]],"voice":[["/voice set","음성, 언어, 엔진 선택"],["/voice list","모든 음성 둘러보기"],["/voice favorites","Open your saved favourite voices"],["/voice recent","Open your recently used voices"],["/voice preview","음성 샘플 들어보기"],["/voice effect","로봇, 에코, 악마… 음성 효과"],["/voice nickname","Vozen이 나를 부르는 방식"],["/voice opt-out","자동 읽기 대상에서 제외"],["/pronunciation","Vozen에게 단어 발음을 가르치기 (나에게만 적용)"]],"fun":[["/game play","16가지 미니게임 중 하나 시작"],["/game leaderboard","서버 상위 플레이어"],["/game stats","나의 점수, 승리, 순위"],["/joke","어떤 언어로든 짧은 농담"],["/laugh","Vozen이 당신의 목소리로 웃습니다"],["/8-ball","매직 8볼에게 소리 내어 질문하기"],["/fact · /fortune · /wyr","재미있는 사실, 운세, 딜레마"],["/birthday set","생일에 Vozen이 노래해줍니다"],["/top-speakers","가장 많이 말한 사람 + 연속 기록"],["/randomizer","Vozen이 무작위로 하나를 골라 말해줍니다"],["/cast","음성 통화의 모든 사람에게 테마 역할을 무작위로 배정하고 결과를 들려줍니다"]],"admin":[["/config greet","통화에 참여하는 사람 인사하기"],["/config language","인터페이스 언어 설정"],["/config default-voice","서버 기본 음성 설정"],["/config auto-read","자동 읽기 켜기/끄기"],["/config block-word","차단 목록 관리"],["/server-pronunciation","서버 전체 발음 (관리자, 3개 · Premium은 50개)"]]};
  var incomingFaq = [["Vozen은 정말 무료인가요?","네 — 핵심 기능은 계속 무료입니다: 35개 언어의 38개 Piper 음성, 자동 읽기, 인사, 대부분의 게임과 모든 관리자 제어. Kokoro와 Google HD는 Premium 엔진이며 Plus는 개인용, 서버 Premium은 서버 전체에 잠금 해제합니다"],["Premium에는 무엇이 포함되나요?","Kokoro 신경망 및 Google HD 엔진, 8가지 음성 효과 전체, 24시간 채널 유지, 개인 발음 50개, /rizz와 Premium 게임이 포함됩니다. 서버 Premium에는 실시간 음성 텍스트 변환도 포함됩니다. 월 €6.99는 서버 2개, €14.99는 5개를 지원하며 Vozen Plus(월 €3.99)는 모든 서버에서 개인 혜택을 제공합니다"],["서버에 Vozen을 어떻게 추가하나요?","\"Discord에 추가\"를 클릭하고, 서버를 선택한 뒤(서버 관리 권한 필요) /setup을 실행하세요. 그게 전부입니다"],["어떤 언어를 지원하나요?","38가지 뉴럴 음성으로 35개 언어를 지원합니다 — 포르투갈어, 영어, 스페인어, 프랑스어, 독일어, 일본어, 아랍어, 러시아어 등 다양한 언어를 각각 원어민 음성으로"],["따로 설정할 게 있나요?","아니요. /setup이 한 단계로 처리합니다. 그 이후에는 합리적인 기본값으로 모든 것이 작동하며 — 나중에 /config로 세부 조정할 수 있습니다"],["모두가 다른 음성을 가질 수 있나요?","네. 각 멤버가 /voice set으로 음성과 언어를 설정합니다. 해당 음성이 기본값이며 메시지별 선택적 언어 감지는 /voice detection on으로 켤 수 있습니다"],["Piper, Kokoro, Google HD 중 어떤 음성 엔진을 써야 하나요?","Piper는 무료 로컬 엔진입니다. Kokoro와 Google HD는 개인 Vozen Plus 또는 서버 Vozen Premium이 필요합니다. /voice set으로 바꿀 수 있으며 이용 기간이 끝나면 무료 엔진으로 자동 복귀합니다"],["기능은 어떻게 끄나요?","모든 것은 /config로 켜고 끌 수 있습니다 — 인사, 자동 읽기, 발화자 안내, 스팸 방지 필터 등등. 전체 킬 스위치도 있습니다"]];
  var dictionary = window.VOZEN_I18N || {};
  dictionary[locale] = Object.assign({}, dictionary[locale] || {}, messages);
  window.VOZEN_I18N = dictionary;
  var commands = window.VOZEN_COMMANDS || {};
  Object.keys(incomingCommands).forEach(function (category) {
    commands[category] = commands[category] || [];
    incomingCommands[category].forEach(function (row, index) {
      var target = commands[category][index];
      if (!target || target[0] !== row[0]) target = commands[category][index] = [row[0], {}];
      target[1][locale] = row[1];
    });
  });
  window.VOZEN_COMMANDS = commands;
  var faq = window.VOZEN_FAQ || [];
  incomingFaq.forEach(function (row, index) {
    var target = faq[index] || (faq[index] = [{}, {}]);
    target[0][locale] = row[0];
    target[1][locale] = row[1];
  });
  window.VOZEN_FAQ = faq;
  try { window.dispatchEvent(new CustomEvent("vozen:i18nready", { detail: { language: locale } })); } catch (_) {}
